+    token: sessionToken,
+    dataMode: UserDataMode.CLOUD,
+    sessionType: params?.isNewUser
+      ? UserSessionType.NEW
+      : UserSessionType.RETURNING,
+    userId: userInfo.id.split("user:")[1],
